nt-size:15px}.dice-widget button:hover{background:#27383b}.ending-actions{display:flex;gap:9px;margin-top:13px}.ending-actions .primary-button{min-width:0}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);padding:11px 18px;background:#e4b56d;color:#1a2528;font-size:11px;font-weight:600;opacity:0;pointer-events:none;transition:.3s;z-index:9}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080e12cc;display:grid;place-items:center;z-index:10;padding:20px}.modal{width:min(420px,100%);padding:34px;background:var(--paper);color:#263235;position:relative;box-shadow:0 20px 70px #0008}.modal h2{font:600 29px var(--serif);margin:0 0 12px}.modal p:not(.eyebrow){font-size:12px;line-height:1.75;color:#59635f;margin-bottom:24px}.modal-close{position:absolute;right:12px;top:10px;border:0;background:none;color:#59635f;font-size:24px}.modal .primary-button{margin-left:auto}
