const archetypes = [
  {id:'warden',name:'The Warden',glyph:'♜',desc:'A steady shield with a lantern-bright sense of duty.',trait:'GRIT +2 · HEART +1',stats:{grit:2,heart:1,wit:0},role:'Guardian'},
  {id:'seeker',name:'The Seeker',glyph:'✧',desc:'A curious trail-reader who notices what others miss.',trait:'WIT +2 · GRIT +1',stats:{grit:1,heart:0,wit:2},role:'Scout'},
  {id:'mender',name:'The Mender',glyph:'❋',desc:'A gentle spellworker who can coax hope from hard places.',trait:'HEART +2 · WIT +1',stats:{grit:0,heart:2,wit:1},role:'Enchanter'}
];
const scenes = {
  arrival:{chapter:1,location:'BRIAR GLEN · DUSK',kicker:'THE CALL TO ADVENTURE',title:'A Light Gone Missing',art:'art-village',text:[`At the edge of Briar Glen, the road narrows beneath a canopy of thorn and pine. The old beacon should be burning on the ridge. Tonight, only a smear of smoke marks its place.`,`Mara Venn, the village keeper, waits beside a handcart stacked with blankets and oil. “The light guides folk home,” she says. “And three nights ago, it began answering something in the hills.”`],choices:[
    {title:'Ask Mara what she heard',detail:'Listen closely; every detail might matter.',check:'wit',dc:10,success:'Mara remembers a melody carried on the wind. You recognize its rhythm as an old warding charm.',failure:'Mara can only recall a low, mournful hum. Still, the fear in her voice tells you this is no ordinary storm.',successFx:{clue:1,xp:1},failureFx:{heart:-1,xp:1},next:'crossroads'},
    {title:'Offer to lead the search',detail:'Give the frightened villagers a reason to hope.',check:'heart',dc:10,success:'Your calm words settle the crowd. Tamsin, a bright-eyed mapmaker, joins your party with a smile.',failure:'Your promise comes out shakier than you hoped, but Tamsin the mapmaker steps forward anyway. “We go together.”',successFx:{trust:1,xp:1,companion:'Tamsin'},failureFx:{trust:1,companion:'Tamsin'},next:'crossroads'},
    {title:'Check your gear and take the north road',detail:'A little preparation can be its own kind of courage.',check:'grit',dc:9,success:'You find a spare flask of lamp oil tucked beneath the blankets. It may come in handy.',failure:'The cart wheel is stuck fast. You lose a little time, but Mara presses a warm flask into your hands.',successFx:{oil:1,xp:1},failureFx:{oil:1},next:'crossroads'}
  ]},
  crossroads:{chapter:2,location:'THE OLD NORTH ROAD · NIGHTFALL',kicker:'WHERE THE PATHS PART',title:'Three Marks in the Mud',art:'art-forest',text:[`The road forks beneath a leaning milepost. Fresh prints cross the mud: a boot heel, a paw, and something narrow that left no track on the way back.`,`From the ridge comes a faint chime. In the trees, a fox watches with a small brass key caught in its collar.`],choices:[
    {title:'Follow the strange, trackless prints',detail:'Read the ground before the rain erases it.',check:'wit',dc:11,success:'The marks form a careful circle around a hidden cairn. Inside: a silver bell-clapper, warm to the touch.',failure:'The trail vanishes in the wet leaves, but you find a silver bell-clapper wedged beneath a stone.',successFx:{clue:1,relic:1,xp:1},failureFx:{relic:1,xp:1},next:'waystone'},
    {title:'Win the fox’s trust',detail:'There is often more than one way to ask a question.',check:'heart',dc:11,success:'The fox trots close and lets you take the key. It gives a knowing little bark toward the ridge.',failure:'The fox darts away, but the key snags on a thorn. Its tag reads “KEEPER.”',successFx:{key:1,trust:1,xp:1},failureFx:{key:1},next:'waystone'},
    {title:'Take the steep path straight to the ridge',detail:'The beacon cannot wait for perfect conditions.',check:'grit',dc:12,success:'You climb through the brambles without a scratch and reach the ridge before the storm.',failure:'A bramble tears your sleeve. You arrive muddy and winded, but the storm has not yet reached the ridge.',successFx:{xp:1},failureFx:{hp:-1,xp:1},next:'waystone'}
  ]},
  waystone:{chapter:3,location:'THE WISHING STONE · DEEP NIGHT',kicker:'A VOICE IN THE FOG',title:'The Keeper’s Promise',art:'art-ruins',text:[`At the ridge’s foot, a moss-covered waystone bears a name almost worn away: Elian Vale, the beacon’s first keeper. A tiny voice slips from the fog. “I only wanted someone to remember.”`,`The beacon above is dark, but not empty. A pale figure stands in its doorway, holding a lantern with no flame. It does not look like a monster. It looks lonely.`],choices:[
    {title:'Speak Elian’s name aloud',detail:'Let the lost keeper know they have not been forgotten.',check:'heart',dc:12,success:'The figure lifts its head. The fog thins, and for a moment the ridge feels like a place someone loved.',failure:'Your voice catches in the cold. The figure hears you all the same; its lantern gives a faint, hopeful pulse.',successFx:{trust:1,xp:1},failureFx:{xp:1},next:'beacon'},
    {title:'Study the waystone for its old ward',detail:'A careful eye may find what the years concealed.',check:'wit',dc:12,success:'A hidden inscription names the beacon’s true purpose: not to warn, but to welcome.',failure:'The inscription is nearly gone. You make out one word: “welcome.”',successFx:{clue:1,xp:1},failureFx:{xp:1},next:'beacon'},
    {title:'Offer the lantern oil as a gift',detail:'A small kindness can light a very long way.',check:'grit',dc:11,success:'The oil catches in the empty lantern with a soft golden glow. Elian lowers their guard.',failure:'The oil spills over the lantern’s rim, yet one bright spark stays behind, like a firefly.',successFx:{oil:-1,trust:1,xp:1},failureFx:{oil:-1,trust:1},next:'beacon'}
  ]},
  beacon:{chapter:4,location:'THE HOLLOW BEACON · MIDNIGHT',kicker:'THE LAST LIGHT',title:'A Door Made of Light',art:'art-cavern',text:[`Inside the tower, a spiral stair descends instead of climbing. At its heart, a dark crystal beats like a sleeping heart. Thin threads of shadow lead from it to Elian’s lantern.`,`Elian speaks from the stairwell. “The beacon kept the village safe, but it kept my promise too. I was told to wait for someone who would come back.” The crystal cracks. The shadows begin to stir.`],choices:[
    {title:'Use the clapper to ring the old bell',detail:'The sound may wake the beacon—or whatever is inside it.',check:'grit',dc:13,success:'The bell answers in a clear, deep note. The shadow threads loosen and the crystal steadies.',failure:'The note comes out cracked, but it is enough to make the shadow recoil.',successFx:{clue:1,xp:1},failureFx:{hp:-1,xp:1},next:'heart'},
    {title:'Remind Elian of the welcome inscription',detail:'A promise can change shape without being broken.',check:'wit',dc:13,success:'Understanding dawns in Elian’s eyes. They were waiting to welcome someone home, not to remain alone.',failure:'The words do not come easily. Elian whispers them along with you: “a place to return to.”',successFx:{trust:1,xp:1},failureFx:{trust:1,xp:1},next:'heart'},
