function renderCompanions(){let base=[{name:state.name,role:archetypes.find(h=>h.id===state.hero).role,glyph:archetypes.find(h=>h.id===state.hero).glyph},...state.companions.map(n=>({name:n,role:n==='Tamsin'?'Mapmaker':'Companion',glyph:'✧'}))];$('companions-panel').innerHTML=`<div class="companions-list">${base.map(c=>`<div class="companion"><span class="companion-icon">${c.glyph}</span><div><b>${esc(c.name)}</b><small>${esc(c.role)}</small></div></div>`).join('')}</div>`}
